int tomoyo_mount(struct tomoyo_request_info *r, char *dev_name,
                 struct path *dir, char *type, unsigned long flags)
{
        struct super_block *sb = dir->mnt->mnt_sb;
        int error = -EPERM;

        if (!type || !*type)
                type = "none";

        r->operation = TOMOYO_OPERATION_MOUNT;
        r->name[0] = dev_name;
        r->name[1] = type;
        r->name[2] = sb->s_type->name;
        r->filename = dir->dentry->d_name.name;
        r->pathname = dir->dentry->d_name.name;

        error = tomoyo_check_acl(r, TOMOYO_FUNC_MOUNT, 0);
        if (error)
                goto out;

        error = 0;
out:
        return error;
}

int tomoyo_mount_acl(struct tomoyo_request_info *r, char *dev_name,
                     struct path *dir, char *type, unsigned long flags)
{
    struct super_block *sb = dir->d_sb;
    int error = -EINVAL;

    if (!type || !sb)
        return error;

    r->operation = TOMOYO_OPERATION_MOUNT;
    r->name[0] = dev_name;
    r->name[1] = type;
    r->filename[0] = dir->d_path.name;

    if (flags & MS_REMOUNT) {
        r->flags |= TOMOYO_FLAG_REMOUNT;
        if (!dev_name)
            return 0;
    }

    if (strcmp(type, "tmpfs") == 0 || strcmp(type, "ramfs") == 0 ||
        strcmp(type, "shm") == 0) {
        r->flags |= TOMOYO_FLAG_VIRTUAL_FS;
        if (!dev_name)
            return 0;
    }

    error = tomoyo_check_acl(r, TOMOYO_TYPE_MOUNT);
    if (error)
        return error;

    tomoyo_log(r);
    return 0;
}

int tomoyo_mount_acl(struct tomoyo_request_info *r, char *dev_name,
                     struct path *dir, char *type, unsigned long flags)
{
    int error = 0;
    struct tomoyo_path_info *dev = NULL;
    struct tomoyo_path_info *dir_name = NULL;

    if (dev_name && *dev_name) {
        dev = tomoyo_get_name(r, dev_name);
        if (IS_ERR(dev))
            return PTR_ERR(dev);
    }

    dir_name = tomoyo_get_name_from_path(r, dir);
    if (IS_ERR(dir_name)) {
        error = PTR_ERR(dir_name);
        goto out;
    }

    r->name[0] = dev;
    r->name[1] = dir_name;
    r->name[2] = tomoyo_get_name(r, type);
    if (IS_ERR(r->name[2])) {
        error = PTR_ERR(r->name[2]);
        goto out;
    }

    error = tomoyo_check_acl(r, TOMOYO_TYPE_MOUNT);
    if (error)
        goto out;

    tomoyo_log(r, "mount");
out:
    if (dev)
        tomoyo_put_name(dev);
    if (dir_name)
        tomoyo_put_name(dir_name);
    return error;
}

int tomoyo_mount_acl(struct tomoyo_request_info *r, char *dev_name, struct path *dir, char *type, unsigned long flags)
{
    struct super_block *sb;
    int error = -EINVAL;

    if (!dir || !dir->dentry || !dir->mnt)
        return -EINVAL;

    r->operation = TOMOYO_OPERATION_MOUNT;
    r->filename = dev_name;
    r->pathname = dir->dentry->d_name.name;
    r->profile = tomoyo_profile(r);
    r->show_log = tomoyo_show_log(r);

    sb = dir->mnt->mnt_sb;
    if (!sb)
        return -EINVAL;

    if (strcmp(type, "none") == 0) {
        dev_name = NULL;
    } else {
        if (!dev_name || strlen(dev_name) >= TOMOYO_PATH_MAX)
            return -ENAMETOOLONG;
    }

    if (tomoyo_check_acl(r)) {
        error = -EACCES;
        goto out;
    }

    error = 0;

out:
    return error;
}

int tomoyo_mount_acl(struct tomoyo_request_info *r, char *dev_name,
                     struct path *dir, char *type, unsigned long flags)
{
    struct super_block *sb;
    int error = -EPERM;

    if (!dir)
        return -EINVAL;

    sb = dir->mnt->mnt_sb;
    if (!sb)
        return -EINVAL;

    if (!(flags & MS_NOACL)) {
        error = tomoyo_check_acl(r, "mount", dev_name, type, dir);
        if (error)
            return error;
    }

    r->operation = TOMOYO_OPERATION_MOUNT;
    r->dev_name = dev_name;
    r->dir = dir;
    r->type = type;
    r->flags = flags;

    tomoyo_log(r);

    return 0;
}
